[metadata] {"type": "update", "filePath": "/workspace/repo/src/suggestions.ts", "content": "import { SUGGEST_PROMPTS_SYSTEM_MESSAGE } from './prompts/index';
import { getDefaultProviders } from './providers/defaults';
import { MAX_SUGGESTIONS_COUNT } from './types/index';
import { accumulateTokenUsage, createEmptyTokenUsage } from './util/tokenUsageUtils';

import type { TokenUsage } from './types/index';

interface GeneratePromptsOutput {
  prompts?: string[];
  error?: string;
  tokensUsed: TokenUsage;
}

/**
 * Generates `num` alternative variants for the given prompt string.
 *
 * `num` must be a positive integer between 1 and {@link MAX_SUGGESTIONS_COUNT}
 * (inclusive). Invalid values return immediately without calling the provider.
 * When at least one call succeeds, the successful outputs are returned. When
 * every call fails, a semicolon-separated, per-variant error string is returned.
 */
export async function generatePrompts(
  prompt: string,
  num: number,
): Promise<GeneratePromptsOutput> {
  if (!Number.isInteger(num) || num < 1 || num > MAX_SUGGESTIONS_COUNT) {
    return {
      error: `num must be an integer between 1 and ${MAX_SUGGESTIONS_COUNT}`,
      prompts: undefined,
      tokensUsed: createEmptyTokenUsage(),
    };
  }

  const provider = (await getDefaultProviders()).suggestionsProvider;
  const tokensUsed = createEmptyTokenUsage();
  const prompts: string[] = [];
  const errors: string[] = [];

  for (let i = 0; i < num; i++) {
    try {
      const resp = await provider.callApi(
        JSON.stringify([
          SUGGEST_PROMPTS_SYSTEM_MESSAGE,
          {
            role: 'user',
            content: 'Generate a variant for the following prompt:',
          },
          {
            role: 'user',
            content: prompt,
          },
        ]),
      );

      accumulateTokenUsage(tokensUsed, resp.tokenUsage);

      if (resp.error || !resp.output) {
        errors.push(resp.error || 'Unknown error');
        continue;
      }

      prompts.push(String(resp.output));
    } catch (err) {
      errors.push(err instanceof Error ? err.message : String(err));
    }
  }

  if (prompts.length === 0) {
    return {
      error: errors.map((err, index) => `Variant ${index + 1}: ${err}`).join('; '),
      prompts: undefined,
      tokensUsed,
    };
  }

  return {
    prompts,
    tokensUsed,
  };
}
